def search_global(request):
    user = request.user
    query = request.GET.get('q', '')
    results = []

    if user.has_role('dispatch'):
        results = Dispatch.objects.filter(name__icontains=query)
    elif user.has_role('payroll'):
        results = PayrollRecord.objects.filter(employee__name__icontains=query)
    elif user.has_role('payment'):
        results = Payment.objects.filter(description__icontains=query)

    return JsonResponse({'results': serialize_results(results)})

